fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    // Helper function to split one string
    fn split_one_line(s: &str, keepends: bool) -> Vec<String> {
        if keepends {
            // Manually split lines, keeping endings
            let mut res = Vec::new();
            let mut start = 0;
            let bytes = s.as_bytes();

            for (i, &b) in bytes.iter().enumerate() {
                if b == b'\n' {
                    // Include the \n at the end
                    let line = &s[start..=i];
                    res.push(line.to_string());
                    start = i + 1;
                }
            }
            // Last line (if any) after the last \n or whole string if no \n present
            if start < s.len() {
                res.push(s[start..].to_string());
            }

            if res.is_empty() {
                // For empty input string, ensure non-empty inner vector
                res.push(String::new());
            }
            res
        } else {
            // Use built-in lines() which strips line endings
            let lines: Vec<String> = s.lines().map(|line| line.to_string()).collect();
            if lines.is_empty() {
                vec![String::new()]
            } else {
                lines
            }
        }
    }

    // Process each string and collect
    a.into_iter()
        .map(|line| split_one_line(&line, keepends))
        .collect()
}